import{_ as o,o as e,c as a,a5 as l}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"918-批量将txt文本文件转换为Word文档（DOCX格式）","日期":"2026-04-19T00:00:00.000Z","修改日期":"2026-05-26T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["TXT文件批处理"],"标签":["TXT批量转DOCX工具","TXT转DOCX","TXT转Word","Word转换工具","小说转Word","批量文本转DOCX","批量转换","文本转Word","文本转换器","文档格式转换"]},"headers":[{"level":2,"title":"你是否遇到过这些情况？","slug":"你是否遇到过这些情况","link":"#你是否遇到过这些情况","children":[]},{"level":2,"title":"实际案例","slug":"实际案例","link":"#实际案例","children":[{"level":3,"title":"案例1：把「小说」文件夹全部转成Word","slug":"案例1-把「小说」文件夹全部转成word","link":"#案例1-把「小说」文件夹全部转成word","children":[]},{"level":3,"title":"案例2：转换到指定文件夹，转换完删除原文件","slug":"案例2-转换到指定文件夹-转换完删除原文件","link":"#案例2-转换到指定文件夹-转换完删除原文件","children":[]},{"level":3,"title":"案例3：批量处理整个硬盘的小说","slug":"案例3-批量处理整个硬盘的小说","link":"#案例3-批量处理整个硬盘的小说","children":[]}]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[{"level":3,"title":"程序使用环境及相关说明","slug":"程序使用环境及相关说明","link":"#程序使用环境及相关说明","children":[]},{"level":3,"title":"程序使用说明","slug":"程序使用说明","link":"#程序使用说明","children":[]}]}],"relativePath":"md/TXT文件批处理/918-批量将txt文本文件转换为Word文档（DOCX格式）.md","filePath":"md/TXT文件批处理/918-批量将txt文本文件转换为Word文档（DOCX格式）.md"}'),r={name:"md/TXT文件批处理/918-批量将txt文本文件转换为Word文档（DOCX格式）.md"};function n(s,t,i,p,d,c){return e(),a("div",null,[...t[0]||(t[0]=[l('<p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-8.png" alt=""></p><p>一个简单粗暴的TXT批量转DOCX工具，扔进去文件夹，点一下按钮，几百个文件瞬间搞定。</p><h2 id="你是否遇到过这些情况" tabindex="-1">你是否遇到过这些情况？ <a class="header-anchor" href="#你是否遇到过这些情况" aria-label="Permalink to &quot;你是否遇到过这些情况？&quot;">​</a></h2><p><strong>场景1：整理素材时</strong></p><blockquote><p>“电脑上堆了几百个TXT笔记，老板说要转成Word格式…”<br> 一个一个另存为？手都要废了！</p></blockquote><p><strong>场景2：电子书管理</strong></p><blockquote><p>“下载了几十本TXT小说，想用Word打开排版…”<br> 一个一个拖进Word，崩溃！</p></blockquote><p><strong>场景3：文档归档</strong></p><blockquote><p>“要把项目文档全部转成可编辑的Word格式…”<br> 复制粘贴到天亮？</p></blockquote><p><strong>现在，一个按钮搞定！</strong></p><h2 id="实际案例" tabindex="-1">实际案例 <a class="header-anchor" href="#实际案例" aria-label="Permalink to &quot;实际案例&quot;">​</a></h2><h3 id="案例1-把「小说」文件夹全部转成word" tabindex="-1">案例1：把「小说」文件夹全部转成Word <a class="header-anchor" href="#案例1-把「小说」文件夹全部转成word" aria-label="Permalink to &quot;案例1：把「小说」文件夹全部转成Word&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>转换前：我的小说/├── 第一章.txt├── 第二章.txt├── 第三章.txt...（100个文件）点击「开始转换」后 ↓转换后：我的小说/├── 第一章.txt├── 第一章.docx  ✅ 新文件├── 第二章.txt├── 第二章.docx  ✅ 新文件├── 第三章.txt├── 第三章.docx  ✅ 新文件...</span></span></code></pre></div><p><strong>操作</strong>：勾选「在原位置转换」，点开始。</p><hr><h3 id="案例2-转换到指定文件夹-转换完删除原文件" tabindex="-1">案例2：转换到指定文件夹，转换完删除原文件 <a class="header-anchor" href="#案例2-转换到指定文件夹-转换完删除原文件" aria-label="Permalink to &quot;案例2：转换到指定文件夹，转换完删除原文件&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入文件夹：D:\\工作文档\\D:\\工作文档\\├── 报告/│   ├── 2023总结.txt│   └── 2024计划.txt└── 笔记/    ├── 会议记录.txt    └── 待办事项.txt输出文件夹：D:\\已转换\\D:\\已转换\\├── 报告/│   ├── 2023总结.docx│   └── 2024计划.docx└── 笔记/    ├── 会议记录.docx    └── 待办事项.docx</span></span></code></pre></div><p><strong>操作</strong>：</p><ol><li>不勾选「在原位置转换」</li><li>选择输出文件夹</li><li>勾选「删除原文件」（谨慎！）</li></ol><hr><h3 id="案例3-批量处理整个硬盘的小说" tabindex="-1">案例3：批量处理整个硬盘的小说 <a class="header-anchor" href="#案例3-批量处理整个硬盘的小说" aria-label="Permalink to &quot;案例3：批量处理整个硬盘的小说&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假设 D:\\小说 下面有：D:\\小说\\├── 玄幻/│   ├── 斗破苍穹.txt│   ├── 凡人修仙传.txt│   └── ...├── 都市/│   ├── 赘婿.txt│   ├── 总裁文.txt│   └── ...└── 悬疑/    ├── 福尔摩斯.txt    └── ...→ 程序会自动扫描所有子文件夹→ 全部转换！</span></span></code></pre></div><p><strong>操作</strong>：选择 D:\\小说 作为输入目录，勾选「在原位置转换」。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 乱码怎么办？</strong></p><blockquote><p>A: 程序会自动尝试UTF-8、GBK等多种编码，99%的情况都能正确识别。如果还乱码，说明原TXT文件本身编码就有问题。</p></blockquote><p><strong>Q: 会删除我的文件吗？</strong></p><blockquote><p>A: 默认不会。只有勾选了「删除原文件」才会删除。删除操作不可恢复，请谨慎！</p></blockquote><p><strong>Q: 支持文件夹嵌套吗？</strong></p><blockquote><p>A: 支持！支持无限层级子文件夹。</p></blockquote><p><strong>Q: 文件名有特殊字符会报错吗？</strong></p><blockquote><p>A: 不会，程序会原样保留文件名。</p></blockquote><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后直接使用即可，程序可以放在任意位置</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2706.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2706.html</a></p>',43)])])}const u=o(r,[["render",n]]);export{g as __pageData,u as default};
